def d(s): return base64.b64decode(s).decode('utf-8')
def parse(argv):
    root, build = '.', True
    i=0
    while i<len(argv):
        if argv[i]=='--root': root=argv[i+1]; i+=2; continue
        if argv[i]=='--no-build': build=False
        i+=1
    return root, build
def write_files(root):
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True)
        c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
def patch(root):
    cache={}
    ap=sk=0
    for f,name,dm,o,nw in EDITS:
        p=os.path.join(root,f)
        if not os.path.exists(p): print("!! introuvable:",f); sys.exit(1)
        src=cache.get(p) or open(p,encoding='utf-8').read()
        marker,old,new=d(dm),d(o),d(nw)
        if marker in src: print("  = déjà",name); cache[p]=src; sk+=1; continue
        if old not in src: print("!! ANCRE KO:",name,"@",f,"— arrêt."); sys.exit(2)
        src=src.replace(old,new,1); cache[p]=src; ap+=1; print("  ~ patché",name)
    for p,src in cache.items(): open(p,'w',encoding='utf-8').write(src)
    print("  ->",ap,"patché(s),",sk,"déjà présent(s).")
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! échec (rc=%d) — rien poussé."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:])
    print("== Bilnov L2 incr.4 (dwg.measure partage) =="); print("[1] fichiers"); write_files(root)
    print("[2] patchs"); patch(root)
    print("[3] prisma + tests"+(" + build" if build else ""))
    if build:
        run(["npx","prisma","generate"],root); run(["npx","prisma","db","push"],root)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Bilnov L2 incr.4 (dwg.measure partage) appliqué%s."%(" (migration + tests + build OK)" if build else " (tests OK)"))
if __name__=='__main__': main()
